function generationPrompt(description) {
  if (typeof description !== "string" || !description.trim()) {
    throw new Error("Enter an image description before running the workflow");
  }
  return `Create a minimalist professional illustration of ${description.trim()}. Use a clean, modern, tech-focused composition with two or three main colors, soft shadows and subtle depth. Put the main subject at the focal point, with supporting elements and subtle connections. Leave about 40% white space and use no text overlay. Use crisp edges, high contrast, matte surfaces, and light from the upper left. Compose it as a square.`;
}

return {
  json: {
    ...{ model: "gpt-image-2.5-flare", n: 1, size: "1024x1024", output_format: "png" },
    prompt: generationPrompt("A person balancing AI autonomy with human oversight"),
  },
};

function inspectPng(response, decode) {
  const encoded =
    Array.isArray(response?.data) && response.data.length === 1
      ? response.data[0]?.b64_json
      : undefined;
  if (
    typeof encoded !== "string" ||
    !encoded ||
    encoded.length > 10_000_000 ||
    encoded.length % 4 !== 0 ||
    !/^[A-Za-z0-9+/]+={0,2}$/.test(encoded) ||
    (response.output_format && response.output_format !== "png")
  ) {
    throw new Error("OpenAI did not return one base64 PNG image");
  }
  const bytes = decode(encoded);
  const signature = [137, 80, 78, 71, 13, 10, 26, 10];
  if (bytes.length < 45 || !signature.every((byte, index) => bytes[index] === byte)) {
    throw new Error("OpenAI returned an invalid PNG signature");
  }

  const view = new DataView(bytes.buffer, bytes.byteOffset, bytes.byteLength);
  let hasImageData = false;
  let offset = 8;
  while (offset + 12 <= bytes.length) {
    const length = view.getUint32(offset);
    const end = offset + 12 + length;
    if (end > bytes.length) break;
    const chunk = String.fromCharCode(...bytes.subarray(offset + 4, offset + 8));
    if (
      offset === 8 &&
      (chunk !== "IHDR" ||
        length !== 13 ||
        view.getUint32(offset + 8) !== 1024 ||
        view.getUint32(offset + 12) !== 1024)
    ) {
      throw new Error("OpenAI did not return the requested 1024 × 1024 PNG");
    }
    if (chunk === "IDAT" && length > 0) hasImageData = true;
    if (chunk === "IEND") {
      if (hasImageData && length === 0 && end === bytes.length) return { bytes, encoded };
      break;
    }
    offset = end;
  }
  throw new Error("OpenAI returned an incomplete PNG");
}

const { encoded } = inspectPng($json, (value) => Buffer.from(value, "base64"));
return { json: { encoded } };

function imgbbReceipt(response) {
  const item = response?.data;
  const size = Number(item?.size);
  if (
    response?.success !== true ||
    response.status !== 200 ||
    typeof item?.id !== "string" ||
    !/^[A-Za-z0-9_-]+$/.test(item.id) ||
    typeof item.url !== "string" ||
    !/^https:\/\/i\.ibb\.co\/[A-Za-z0-9_-]+\/[A-Za-z0-9_%.~-]+$/i.test(item.url) ||
    !Number.isSafeInteger(size) ||
    size < 1
  ) {
    throw new Error("ImgBB did not confirm an uploaded image with a direct HTTPS URL");
  }
  return { url: item.url, size };
}

return { json: imgbbReceipt($json) };

function checkShrink({ url, id, info, outputMime }) {
  const match =
    typeof url === "string" && /^https:\/\/api\.tinify\.com\/output\/([A-Za-z0-9_-]+)$/.exec(url);
  if (!match || (id !== undefined && id !== match[1])) {
    throw new Error("Tinify returned an invalid output URL");
  }
  if (info?.type !== outputMime || !Number.isSafeInteger(info.size) || info.size < 1) {
    throw new Error("Tinify returned invalid output metadata");
  }
  return { imageId: match[1], size: info.size };
}

function compressionReceipt(original, input, result) {
  if (
    input?.type !== "image/png" ||
    input.size !== original.size ||
    result?.width !== 1024 ||
    result.height !== 1024 ||
    !Number.isSafeInteger(result.size) ||
    result.size < 1 ||
    result.size > input.size
  ) {
    throw new Error("Tinify returned unexpected metadata for the original PNG");
  }
  return { originalUrl: original.url, originalBytes: input.size, optimizedBytes: result.size };
}

const original = $("Read the original ImgBB link").item.json;
const result = $json.output;
checkShrink({ url: result?.url, info: result, outputMime: "image/png" });
return { json: { url: result.url, sizes: compressionReceipt(original, $json.input, result) } };

function checkBytes({ bytes, mime, outputMime, expectedSize }) {
  const at = (offset, length) => Array.from(bytes.subarray(offset, offset + length));
  const ascii = (offset, length) => String.fromCharCode(...at(offset, length));
  const signature = (expected) => expected.every((value, index) => bytes[index] === value);
  const headers = {
    "image/png": () => signature([137, 80, 78, 71, 13, 10, 26, 10]),
    "image/jpeg": () => signature([255, 216, 255]),
    "image/webp": () => ascii(0, 4) === "RIFF" && ascii(8, 4) === "WEBP",
    "image/avif": () => ascii(4, 4) === "ftyp" && ["avif", "avis"].includes(ascii(8, 4)),
    "image/jxl": () =>
      signature([255, 10]) || signature([0, 0, 0, 12, 74, 88, 76, 32, 13, 10, 135, 10]),
  };
  if (
    String(mime ?? "")
      .split(";")[0]
      .toLowerCase() !== outputMime ||
    bytes.length !== expectedSize ||
    !headers[outputMime]?.()
  ) {
    throw new Error("Tinify did not return the complete expected image");
  }
}

const item = $input.item;
const sizes = $("Check the compression receipt").item.json.sizes;
const bytes = await helpers.getBinaryDataBuffer($itemIndex, "data");
checkBytes({
  bytes,
  mime: item.binary.data.mimeType,
  outputMime: "image/png",
  expectedSize: sizes.optimizedBytes,
});
item.binary.data.fileName = "optimized.png";
return { json: sizes, binary: item.binary };

function imgbbReceipt(response) {
  const item = response?.data;
  const size = Number(item?.size);
  if (
    response?.success !== true ||
    response.status !== 200 ||
    typeof item?.id !== "string" ||
    !/^[A-Za-z0-9_-]+$/.test(item.id) ||
    typeof item.url !== "string" ||
    !/^https:\/\/i\.ibb\.co\/[A-Za-z0-9_-]+\/[A-Za-z0-9_%.~-]+$/i.test(item.url) ||
    !Number.isSafeInteger(size) ||
    size < 1
  ) {
    throw new Error("ImgBB did not confirm an uploaded image with a direct HTTPS URL");
  }
  return { url: item.url, size };
}

const hosted = imgbbReceipt($json);
const sizes = $("Check the compression receipt").item.json.sizes;
if (hosted.size !== sizes.optimizedBytes)
  throw new Error("ImgBB did not confirm the expected optimized file size");
return { json: { ...sizes, optimizedUrl: hosted.url } };
